function promisify(fn) {
  return function (...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, value) => (error ? reject(error) : resolve(value)));
    });
  };
}

const garage = {
  cars: 4,
  free(callback) {
    callback(null, 10 - this.cars);
  },
};

garage.freeAsync = promisify(garage.free);
const freeAsync = garage.freeAsync;

garage.freeAsync().then((n) => console.log("free: " + n));
freeAsync().catch((error) => console.log(error.name));
